// ═══════════════════════════════════════════════════════════════
// RATE LIMIT & COMMANDS + DOCUMENT DETECTION (UNIFIED)
// Łączy logikę z Chat Bot + wykrywanie dokumentów z K2BUD
// ═══════════════════════════════════════════════════════════════

const telegramData = $input.first().json;
const chatId = telegramData.message.chat.id;
const userMessage = telegramData.message.text || telegramData.message.caption || '';
const userName = telegramData.message.from.first_name || 'User';
const hasPhoto = telegramData.message.photo && telegramData.message.photo.length > 0;
const hasDocument = telegramData.message.document;

// ═══════════════════════════════════════════════════════════════
// RATE LIMITING (z Chat Bot)
// ═══════════════════════════════════════════════════════════════
const now = Date.now();
const globalData = $getWorkflowStaticData('global'); // ✅ Poprawna składnia
const rateLimits = globalData.rateLimits || {};
const userKey = `limit_${chatId}`;
const userLimit = rateLimits[userKey] || { count: 0, resetAt: now + 60000 };

if (now >= userLimit.resetAt) {
  userLimit.count = 0;
  userLimit.resetAt = now + 60000;
}

if (userLimit.count >= 10) {
  const waitSeconds = Math.ceil((userLimit.resetAt - now) / 1000);
  return [{
    json: {
      routeTo: 'COMMAND',
      isCommand: true,
      chatId: chatId,
      response: `⏱️ Wysłałeś za dużo wiadomości!\n\nLimit: 10 wiadomości/minutę\nSpróbuj ponownie za ${waitSeconds} sekund.`
    }
  }];
}

userLimit.count++;
rateLimits[userKey] = userLimit;
globalData.rateLimits = rateLimits;

// ═══════════════════════════════════════════════════════════════
// WYKRYWANIE DOKUMENTÓW (nowe - z K2BUD)
// ═══════════════════════════════════════════════════════════════
if (hasDocument) {
  const document = telegramData.message.document;
  const fileName = document.file_name || 'document';
  const mimeType = document.mime_type || '';

  // Sprawdź czy to dokument do klasyfikacji (PDF, DOCX, obrazy)
  const isClassifiableDocument = 
    mimeType.includes('pdf') ||
    mimeType.includes('word') ||
    mimeType.includes('document') ||
    mimeType.includes('image') ||
    fileName.match(/\.(pdf|docx?|xlsx?|jpg|jpeg|png|gif)$/i);

  if (isClassifiableDocument) {
    return [{
      json: {
        routeTo: 'DOCUMENT',
        isCommand: false,
        hasDocument: true,
        hasPhoto: false,
        document: document,
        chatId: chatId,
        userName: userName,
        userMessage: userMessage || ''
      }
    }];
  } else {
    // Nieobsługiwany typ dokumentu
    return [{
      json: {
        routeTo: 'COMMAND',
        isCommand: true,
        chatId: chatId,
        response: `📎 Otrzymałem plik: ${fileName}\n\nNiestety ten typ pliku (${mimeType}) nie jest jeszcze obsługiwany.\n\nObsługuję: PDF, DOCX, XLSX, JPG, PNG`
      }
    }];
  }
}

// ═══════════════════════════════════════════════════════════════
// WYKRYWANIE ZDJĘĆ (z Chat Bot)
// ═══════════════════════════════════════════════════════════════
if (hasPhoto) {
  const photo = telegramData.message.photo[telegramData.message.photo.length - 1];
  const photoFileId = photo.file_id;

  return [{
    json: {
      routeTo: 'PHOTO',
      isCommand: false,
      hasPhoto: true,
      hasDocument: false,
      photoFileId: photoFileId,
      chatId: chatId,
      userName: userName,
      userMessage: userMessage || 'Co widzisz na tym zdjęciu?',
      conversationHistory: globalData[`chat_${chatId}`] || []
    }
  }];
}

// ═══════════════════════════════════════════════════════════════
// SPRAWDZENIE PUSTEJ WIADOMOŚCI
// ═══════════════════════════════════════════════════════════════
if (!userMessage || userMessage.trim() === '') {
  return [{
    json: {
      routeTo: 'COMMAND',
      isCommand: true,
      chatId: chatId,
      response: '🤔 Nie otrzymałem żadnej wiadomości tekstowej. Napisz coś, a chętnie odpowiem!'
    }
  }];
}

// ═══════════════════════════════════════════════════════════════
// KOMENDY (z Chat Bot)
// ═══════════════════════════════════════════════════════════════
const conversationHistory = globalData[`chat_${chatId}`] || [];

if (userMessage === '/start' || userMessage === '/help') {
  return [{
    json: {
      routeTo: 'COMMAND',
      isCommand: true,
      chatId: chatId,
      response: `👋 Cześć ${userName}!\n\nJestem K2BUD Unified Agent - łączę:
\n• 🤖 Chat z Claude AI (pytania, programowanie)\n• 📸 Analiza zdjęć (Claude Vision)\n• 📁 Klasyfikacja dokumentów (auto-upload do Drive)\n\n📝 Komendy:\n/clear - wyczyść historię\n/stats - pokaż statystyki\n/help - ta wiadomość\n\n💡 Wyślij:\n• Tekst - zadaj pytanie\n• Zdjęcie - przeanalizuję\n• PDF/DOCX - sklasyfikuję i zapiszę na Drive`
    }
  }];
}

if (userMessage === '/clear' || userMessage === '/reset') {
  delete globalData[`chat_${chatId}`];
  return [{
    json: {
      routeTo: 'COMMAND',
      isCommand: true,
      chatId: chatId,
      response: '🧹 Historia konwersacji została wyczyszczona!\n\nMożesz zacząć nową rozmowę.'
    }
  }];
}

if (userMessage === '/stats') {
  const userMessages = conversationHistory.filter(m => m.role === 'user').length;
  const assistantMessages = conversationHistory.filter(m => m.role === 'assistant').length;
  const totalChars = conversationHistory.reduce((sum, m) => sum + (m.content?.length || 0), 0);
  const documentsCount = globalData[`documents_${chatId}`] || 0;

  return [{
    json: {
      routeTo: 'COMMAND',
      isCommand: true,
      chatId: chatId,
      response: `📊 Statystyki K2BUD Unified Agent:\n\n💬 Konwersacja:\n• Wszystkich wiadomości: ${conversationHistory.length}\n• Twoich wiadomości: ${userMessages}\n• Odpowiedzi Claude: ${assistantMessages}\n• Znaków w historii: ${totalChars}\n\n📁 Dokumenty:\n• Zarchiwizowanych: ${documentsCount}\n\n⏱️ Rate limit:\n• W tej minucie: ${userLimit.count}/10`
    }
  }];
}

// ═══════════════════════════════════════════════════════════════
// TEKST - CHAT (z Chat Bot)
// ═══════════════════════════════════════════════════════════════
const cleanedHistory = conversationHistory.filter(m => m.content && m.content.trim() !== '');
globalData[`chat_${chatId}`] = cleanedHistory;

if (userMessage && userMessage.trim() !== '') {
  cleanedHistory.push({
    role: 'user',
    content: userMessage
  });
}

if (cleanedHistory.length > 20) {
  const toRemove = cleanedHistory.length - 20;
  cleanedHistory.splice(0, toRemove);
}

globalData[`chat_${chatId}`] = cleanedHistory;

return [{
  json: {
    routeTo: 'CHAT',
    isCommand: false,
    hasPhoto: false,
    hasDocument: false,
    chatId: chatId,
    userName: userName,
    conversationHistory: cleanedHistory,
    currentMessage: userMessage
  }
}];
